  "WSL backend couldn't start: {preflightError}":
    "WSL バックエンドを起動できませんでした: {preflightError}",
  Off: "オフ",
  "Default distro": "既定のディストリビューション",
  "Run WSL only": "WSL のみ実行",
  "Enable Tailscale HTTPS": "Tailscale HTTPS を有効にする",
  "Not encrypted: anyone on the same network can capture the sign-in. For remote access, use SpecWithCode Connect or Tailscale HTTPS.":
    "暗号化されていません。同じネットワーク上の誰でもサインイン情報を取得できます。リモートアクセスには SpecWithCode Connect か Tailscale HTTPS を使ってください。",
  "More actions for this machine": "このマシンのその他の操作",
  "Up to date": "最新です",
  "This connection can create access links but cannot view authorized clients.":
    "この接続ではアクセスリンクを作成できますが、承認済みクライアントは表示できません。",
  "Enable network access?": "ネットワークアクセスを有効にしますか？",
  "Disable network access?": "ネットワークアクセスを無効にしますか？",
  "Let your other devices connect to SpecWithCode over your local network. This mode uses plain HTTP, so its traffic is not encrypted: anyone on the same network can capture the sign-in and use it to control the app. Turn it on only on a network you trust, and use SpecWithCode Connect or Tailscale HTTPS for remote access. Pair devices to give them access. The app will restart.":
    "他のデバイスからローカルネットワーク経由で SpecWithCode に接続できるようにします。このモードは通常の HTTP を使うため通信は暗号化されません。同じネットワーク上の誰でもサインイン情報を取得し、アプリを操作できてしまいます。信頼できるネットワークでのみオンにし、リモートアクセスには SpecWithCode Connect か Tailscale HTTPS を使ってください。アクセスを許可するにはデバイスをペアリングします。アプリは再起動します。",
  "Devices connected over your local network will disconnect. Existing tunnels, such as SpecWithCode Connect or Tailscale HTTPS, keep working. SpecWithCode will restart.":
    "ローカルネットワーク経由で接続しているデバイスは切断されます。SpecWithCode Connect や Tailscale HTTPS などの既存のトンネルは引き続き動作します。SpecWithCode は再起動します。",
  "Restarting…": "再起動しています…",
  "Restart and enable": "再起動して有効にする",
  "Restart and disable": "再起動して無効にする",
  "Turn off WSL and switch back to Windows?": "WSL をオフにして Windows に戻しますか？",
  "Disable WSL backend?": "WSL バックエンドを無効にしますか？",
  "Switch WSL distro?": "WSL のディストリビューションを切り替えますか？",
  "Start the WSL backend": "WSL バックエンドを起動",
  "Run only the WSL backend?": "WSL バックエンドのみ実行しますか？",
  "Re-enable the Windows backend?": "Windows バックエンドを再び有効にしますか？",
  "SpecWithCode will restart on the Windows backend. Threads and projects opened against WSL stay safe inside the distro and become available again when you re-enable WSL.":
    "SpecWithCode は Windows バックエンドで再起動します。WSL で開いたスレッドとプロジェクトはディストリビューション内に安全に残り、WSL を再び有効にすると使えるようになります。",
  "The WSL backend will stop. Threads and projects opened against WSL stay safe inside the distro, but they'll be unavailable in SpecWithCode until you re-enable WSL.":
    "WSL バックエンドは停止します。WSL で開いたスレッドとプロジェクトはディストリビューション内に安全に残りますが、WSL を再び有効にするまで SpecWithCode では使えません。",
  "SpecWithCode will restart the WSL backend on the new distro. Sessions still running on the current distro will be interrupted.":
    "SpecWithCode は新しいディストリビューションで WSL バックエンドを再起動します。現在のディストリビューションで実行中のセッションは中断されます。",
  "Run the WSL backend alongside the Windows one, or stop the Windows backend and use only WSL? You can change this later from Settings.":
    "WSL バックエンドを Windows バックエンドと並行して実行しますか、それとも Windows バックエンドを止めて WSL のみ使いますか？ 後から設定で変更できます。",
  "SpecWithCode will restart and start only the WSL backend. Your Windows-side projects won't be accessible until you turn this off again.":
    "SpecWithCode は再起動して WSL バックエンドのみを起動します。これをオフに戻すまで、Windows 側のプロジェクトにはアクセスできません。",
  "SpecWithCode will restart and bring the Windows backend back up alongside WSL.":
    "SpecWithCode は再起動し、WSL と並行して Windows バックエンドを再び起動します。",
  "Applying…": "適用しています…",
  "Use only WSL": "WSL のみ使う",
  "Run both backends": "両方のバックエンドを実行",
  "Disable WSL": "WSL を無効にする",
  "Switch distro": "ディストリビューションを切り替え",
  "Disable Tailscale HTTPS?": "Tailscale HTTPS を無効にしますか？",
