  "Checking SpecWithCode Connect…": "SpecWithCode Connect を確認しています…",
  "Link SpecWithCode Connect first": "先に SpecWithCode Connect をリンクしてください",
  "The line carries this machine’s SpecWithCode Connect address, so your main machine can reach it from anywhere. This updates on its own once Connect is linked here. Your main machine does not need to be signed in.":
    "この行にはこのマシンの SpecWithCode Connect アドレスが含まれるため、メインマシンはどこからでもアクセスできます。ここで Connect をリンクすると自動で更新されます。メインマシンでのサインインは不要です。",
  "SpecWithCode Connect is linked on this machine, so you can make the line now. No sign-in is needed in this window.":
    "このマシンでは SpecWithCode Connect がリンク済みなので、今すぐ行を作成できます。このウィンドウでのサインインは不要です。",
  "Your main machine can then start work here. The line carries this machine’s SpecWithCode Connect address, so link Connect here first. After that, the main machine’s own keys reach this machine; no one needs to stay signed in.":
    "その後、メインマシンからここで作業を開始できます。この行にはこのマシンの SpecWithCode Connect アドレスが含まれるため、先にここで Connect をリンクしてください。以降はメインマシン自身の鍵でこのマシンにアクセスでき、誰もサインインしたままでいる必要はありません。",
  "Search fonts…": "フォントを検索…",
  "No fonts found.": "フォントが見つかりません。",
  "Hidden account": "非表示のアカウント",
  "Choose which {code} login each GitHub host uses, or turn a host off.":
    "各 GitHub ホストが使う {code} のログインを選ぶか、ホストをオフにします。",
  "Hide GitHub accounts": "GitHub アカウントを隠す",
  "Reveal GitHub accounts": "GitHub アカウントを表示",
  "Signed in as": "サインイン中のアカウント",
  "Active gh account{value}": "アクティブな gh アカウント{value}",
  "The chosen login is no longer signed in, so the active gh login is used.":
    "選んだログインはサインインが切れているため、アクティブな gh ログインを使います。",
  "Use active login": "アクティブなログインを使う",
  "can't be used: {value}": "使用できません: {value}",
  "{environmentVariable} is set on the server, so it overrides the account chosen here until it is unset.":
    "サーバーで {environmentVariable} が設定されているため、解除されるまでここで選んだアカウントより優先されます。",
  "When adding a machine, copy this machine's GitHub sign-in":
    "マシンを追加するときに、このマシンの GitHub サインインをコピーする",
  "The token goes to that machine's secret store over the tailnet and is used by SpecWithCode only. Off: a one-time code is offered first.":
    "トークンは tailnet 経由でそのマシンのシークレットストアに送られ、SpecWithCode だけが使います。オフの場合は、まずワンタイムコードを提示します。",
  "Ask before copying": "コピーする前に確認",
  "Ask before copying this machine's GitHub sign-in":
    "このマシンの GitHub サインインをコピーする前に確認",
  "gh on {environmentLabel}: {value}. SpecWithCode never switches or removes it.":
    "{environmentLabel} の gh: {value}。SpecWithCode が切り替えたり削除したりすることはありません。",
  "SpecWithCode's pull requests and reviews on {environmentLabel}, and the agents, terminals and git it starts there, use the copied sign-in for github.com over HTTPS; it wins over GH_TOKEN and gh there. {environmentLabel2}'s gh logins, git config and credential helpers stay as they were, and SSH remotes keep using SSH keys.":
    "{environmentLabel} での SpecWithCode のプルリクエストとレビュー、そこで起動するエージェント、ターミナル、git は、HTTPS 経由の github.com にコピーしたサインインを使い、そこでの GH_TOKEN や gh より優先されます。{environmentLabel2} の gh ログイン、git の設定、認証情報ヘルパーはそのままで、SSH のリモートは引き続き SSH 鍵を使います。",
  " (one for github.com)": " （github.com 用に 1 つ）",
  "Confirm copying the GitHub sign-in": "GitHub サインインのコピーを確認",
  "Copy {login}'s GitHub sign-in ({value}) from {sourceLabel}? It is stored only in {environmentLabel}'s secret store and can be removed here; revoking it on GitHub signs out every machine using it.{value2}":
    "{sourceLabel} から {login} の GitHub サインイン（{value}）をコピーしますか？ {environmentLabel} のシークレットストアにのみ保存され、ここで削除できます。GitHub で取り消すと、それを使うすべてのマシンでサインアウトされます。{value2}",
  "Copy sign-in": "サインインをコピー",
  "{checkbox}Don't ask again": "{checkbox}今後は確認しない",
  "Don't ask again": "今後は確認しない",
  "Remove copied sign-in": "コピーしたサインインを削除",
  "Use gh's {otherGhLogin} for SpecWithCode instead":
    "代わりに gh の {otherGhLogin} を SpecWithCode に使う",
  "Machines you trust here can read PR data through each other's GitHub access. Enable both machines. Read and act may use broader permissions than the machine that owns them. This applies only to this device.":
    "ここで信頼するマシン同士は、互いの GitHub アクセスを通じて PR データを読めます。両方のマシンを有効にしてください。読み取りと操作には、所有するマシンより広い権限が使われる場合があります。このデバイスにのみ適用されます。",
  "Sign in from here: {environmentLabel} runs gh, you approve it on github.com in this browser. The sign-in stays on {environmentLabel2}.":
    "ここからサインイン: {environmentLabel} が gh を実行し、このブラウザーで github.com 上で承認します。サインイン情報は {environmentLabel2} に残ります。",
  "Starting gh on {environmentLabel}…": "{environmentLabel} で gh を起動しています…",
  "Open {value} on this device, enter this code and approve. The sign-in is saved on {environmentLabel} only.":
    "このデバイスで {value} を開き、このコードを入力して承認してください。サインイン情報は {environmentLabel} にのみ保存されます。",
