  "Adding a Linux server you rent? Start with the {a}.":
    "レンタルした Linux サーバーを追加しますか？ まず{a}をご覧ください。",
  "Linux worker guide": "Linux ワーカーガイド",
  "Link SpecWithCode Connect here first, then make a line to paste on your main machine.":
    "まずここで SpecWithCode Connect をリンクし、メインのマシンに貼り付ける行を作成してください。",
  "Make a join line": "参加用の行を作成",
  "To connect one, open a pairing link from this server’s owner with {value}, or use Add environment with that machine’s own link.":
    "接続するには、このサーバーの所有者から届いたペアリングリンクを {value} で開くか、そのマシン自身のリンクで「環境を追加」を使ってください。",
  "Turn Auto off": "Auto をオフにする",
  "Long audio is transcribed first (speech to text), the transcript is split into chunks that fit the model's context, and the cheaper model works through the chunks. Auto never sends audio to a model that cannot hear it.":
    "長い音声はまず文字起こしされ（音声からテキスト）、文字起こしはモデルのコンテキストに収まるチャンクに分割され、より安いモデルが順に処理します。Auto は音声を聞けないモデルに音声を送ることはありません。",
  "A failure on the cheaper model gets one retry on the model the work would have used without Auto. Model changes happen only between turns.":
    "より安いモデルで失敗した場合、Auto なしで使われていたはずのモデルで 1 回だけ再試行します。モデルの切り替えはターンの合間にのみ行われます。",
  "Routing conflicts": "ルーティングの競合",
  "task tiers": "タスクのティア",
  "Default ({value})": "デフォルト（{value}）",
  "Let Auto use paid API models?": "Auto に有料 API モデルの使用を許可しますか？",
  "Workers in this project may run on providers billed per token, up to the tier you picked. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "このプロジェクトのワーカーは、選んだティアまでのトークン課金のプロバイダーで実行される場合があります。それらのターンは API 料金でプロバイダーの API アカウントに請求されます。SpecWithCode はその残高を読み取ったり上限を設けたりできないため、プロバイダー側で支出上限を設定してください。",
  "Workers may run on providers billed per token, up to the tier you picked, in every project that does not override this. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "ワーカーは、これを上書きしていないすべてのプロジェクトで、選んだティアまでのトークン課金のプロバイダーで実行される場合があります。それらのターンは API 料金でプロバイダーの API アカウントに請求されます。SpecWithCode はその残高を読み取ったり上限を設けたりできないため、プロバイダー側で支出上限を設定してください。",
